Level Order Traversal technique is a method to traverse a Tree such that all nodes present in the same level are traversed completely before traversing the next level.Input:  Output: [[5], [12, 13], [7, 14, 2], [17, 23, 27, 3, 8, 11]]Explanation:  Start with the root - [5]Level 1: [12, 13]Level 2: [7, 14, 2]Level 3: [17, 23, 27, 3, 8, 11]Try It YourselfTable of Content[Approach] Using Recursion - O(n) time and O(n) space[Expected Approach] Using Queue (Iterative) - O(n) time and O(n) space[Approach] Using Recursion - O(n) time and O(n) spaceThe idea is to traverse the tree recursively, starting from the root at level 0. When a node is visited, its value is added to the result array at the index corresponding to its level, and then its left and right children are recursively processed in the same way. This effectively performs a level-order traversal using recursion.
            C++

    #include <iostream>
#include<vector>
using namespace std;

class Node {
public:
    int data;
    Node *left, *right;

    // Constructor to initialize a new node
    Node(int value) {
        data = value;
        left = nullptr;
        right = nullptr;
    }
};

void levelOrderRec(Node* root, int level, vector<vector<int>>& res) {
    // Base case
    if (root == nullptr) return;

    // Add a new level to the result if needed
    if (res.size() <= level)
        res.push_back({});

    // Add current node's data to its corresponding level
    res[level].push_back(root->data);

    // Recur for left and right children
    levelOrderRec(root->left, level + 1, res);
    levelOrderRec(root->right, level + 1, res);
}

// Function to perform level order traversal
vector<vector<int>> levelOrder(Node* root) {

    // Stores the result level by level
    vector<vector<int>> res; 

    levelOrderRec(root, 0, res);
    return res;
}

int main() {
    //      5
    //     / \
    //   12   13
    //   /  \    \
    //  7    14   2
    // / \  /  \  / \
    //17 23 27 3  8  11

    Node* root = new Node(5);
    root->left = new Node(12);
    root->right = new Node(13);

    root->left->left = new Node(7);
    root->left->right = new Node(14);

    root->right->right = new Node(2);

    root->left->left->left = new Node(17);
    root->left->left->right = new Node(23);

    root->left->right->left = new Node(27);
    root->left->right->right = new Node(3);

    root->right->right->left = new Node(8);
    root->right->right->right = new Node(11);

    vector<vector<int>> res = levelOrder(root);

    for (vector<int> level : res) {
        for (int val : level) {
            cout << val << " ";
        }
        cout << endl; 
    }

    return 0;
}


